#!/bin/zsh
# usage: merge.sh <pr>  — squash-merge with an explicit body (no trailers), then ff local main
R=FSM1/cipher-box; P=$1; cd /Users/myankelev/.claude/scratch/w1963
msgs=$(env -u GITHUB_TOKEN gh api repos/$R/pulls/$P/commits --jq '.[].commit.message') || { echo "ABORT: commits fetch failed"; exit 1; }
[ -z "$msgs" ] && { echo "ABORT: no commits read"; exit 1; }
n=$(echo "$msgs" | grep -ci 'co-authored\|generated with'); echo "trailers in commits: $n"
[ "$n" != "0" ] && { echo "ABORT: trailers present"; exit 1; }
ms=$(env -u GITHUB_TOKEN gh api repos/$R/pulls/$P --jq .mergeable_state); echo "mergeable_state: $ms"
[ "$ms" = "dirty" ] && { echo "ABORT: branch conflicts with main; rebase first"; exit 1; }
T=$(env -u GITHUB_TOKEN gh pr view $P -R $R --json title --jq .title)
env -u GITHUB_TOKEN gh pr view $P -R $R --json body --jq .body | grep -vi 'co-authored\|generated with' > body-$P.md
[ -s body-$P.md ] || { echo "ABORT: body file empty (API error?)"; exit 1; }
env -u GITHUB_TOKEN gh pr ready $P -R $R >/dev/null
env -u GITHUB_TOKEN gh pr merge $P -R $R --squash --delete-branch --subject "$T (#$P)" --body-file body-$P.md 2>&1 | tail -1
env -u GITHUB_TOKEN gh pr view $P -R $R --json state,mergedAt,mergeCommit --jq '"\(.state) \(.mergedAt) \(.mergeCommit.oid[:9])"'
cd /Users/myankelev/Code/random/cipher-box && git fetch -q origin && git merge -q --ff-only origin/main && git log -1 --format='%h %s'

