commit 7e12c9d90cdc3351a7d91a184cde5bb0bdc1abfd
Author: Michael Yankelev <myankelev@gmail.com>
Date:   Sat Sep 26 04:43:08 2026 +0200

    fix(web): re-read the share dialog on a snapshot update

    A conversion pass that moves only the pending or refused claim counts
    emits snapshotUpdated and no granteeJoined. When the dialog open meets
    a running pass, it does no read of its own, so the counts stayed stale
    until the owner opened the dialog again.

    The hook now re-reads the sharing view on snapshotUpdated. One re-read
    runs at a time, and a burst of events folds into one trailing read. A
    sharing read emits no snapshotUpdated, so the re-read cannot loop.

diff --git a/apps/web/src/hooks/useSharingActions.ts b/apps/web/src/hooks/useSharingActions.ts
index 390a0c3d9..f2feb7e8d 100644
--- a/apps/web/src/hooks/useSharingActions.ts
+++ b/apps/web/src/hooks/useSharingActions.ts
@@ -127,11 +127,33 @@ export function useSharingActions(scope: Uint8Array): SharingActions {
   const [joined, setJoined] = useState<string | null>(null);
   useEffect(() => {
     if (client === null) return;
+    // One re-read at a time: a burst of events folds into one trailing read. A
+    // sharing read emits no `snapshotUpdated`, so a re-read cannot loop.
+    let reading = false;
+    let again = false;
+    const reread = () => {
+      if (reading) {
+        again = true;
+        return;
+      }
+      reading = true;
+      // A failed re-read leaves the last view drawn.
+      void read(client.facade)
+        .catch(() => undefined)
+        .finally(() => {
+          reading = false;
+          if (again) {
+            again = false;
+            reread();
+          }
+        });
